import type {ImageDefinition} from '../types/types'
import {ImageDefinitionGenericStatusIndicator} from './ImageDefinitionGenericStatusIndicator'
import styles from '../styles/components/ImageHeaderDescription.module.css'
import type {RunnerGroup} from '../types/payloads'

interface CustomImageHeaderDescriptionProps {
  customImage: ImageDefinition
  runnerGroup?: RunnerGroup
}

export function CustomImageHeaderDescription(props: CustomImageHeaderDescriptionProps) {
  const runnerGroupTitle = props.runnerGroup
    ? `${props.runnerGroup.name} (Id ${props.customImage.runnerGroupId})`
    : props.customImage.runnerGroupId
      ? `Id ${props.customImage.runnerGroupId}`
      : 'None'

  return (
    <div className={styles.headerContainer}>
      <div className="col-8 d-inline-block v-align-top">
        <div>
          <span className="color-fg-muted">Image Definition Id: </span>
          <span>{props.customImage.id}</span>
        </div>
        <div>
          <span className="color-fg-muted">Name: </span>
          <span>{props.customImage.name}</span>
        </div>
        <div>
          <span className="color-fg-muted">Owner: </span>
          <span>{props.customImage.ownerId}</span>
        </div>
        <div>
          <span className="color-fg-muted">Total Size: </span>
          <span>{props.customImage.totalImageVersionsSizeGb} GB</span>
        </div>
      </div>
      <div className="col-4 d-inline-block v-align-top">
        <div>
          <span className="color-fg-muted">Runner Group: </span>
          <span>{runnerGroupTitle}</span>
        </div>
        <div>
          <span className="color-fg-muted">OS Type: </span>
          <span>{props.customImage.osType}</span>
        </div>
        <div>
          <span className="color-fg-muted">Architecture: </span>
          <span>{props.customImage.architecture}</span>
        </div>
        <div>
          <span className="color-fg-muted">Enabled: </span>
          <span>
            <ImageDefinitionGenericStatusIndicator value={props.customImage.enabled} />
          </span>
        </div>
      </div>
    </div>
  )
}
