import {Breadcrumbs} from '@primer/react'
import {useNavigate} from '@github-ui/use-navigate'
import type {ImageDefinition} from '../types/types'
import {customImages} from '../helpers/constants'
import styles from '../styles/components/Breadcrumbs.module.css'

interface CustomImageBreadcrumbsProps {
  imageDefinition: ImageDefinition
  baseUrl: string
}

export function CustomImageBreadcrumbs(props: CustomImageBreadcrumbsProps) {
  const navigate = useNavigate()

  const imageDefinitionTitle = `${props.imageDefinition.name} (ID ${props.imageDefinition.id})`

  const breadcrumbsItems = [
    <Breadcrumbs.Item key="image_definition" className={styles.clickableItem} onClick={() => navigate(props.baseUrl)}>
      {customImages.BreadcrumbTitle}
    </Breadcrumbs.Item>,
    <Breadcrumbs.Item key="image_title" selected>
      {imageDefinitionTitle}
    </Breadcrumbs.Item>,
  ]

  return (
    <div className={styles.breadcrumbsContainer}>
      <Breadcrumbs>{...breadcrumbsItems}</Breadcrumbs>
    </div>
  )
}
