import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {customImagesStafftoolsAppBuilder} from './config/app-builder'
import {customImagesRoute} from './routes/custom-images-list-route'
import {
  CustomImageListPageEntrypointForEnterprise,
  CustomImageListPageEntrypointForOrg,
} from './routes/CustomImagesListPage'
import {customImageVersionsRoute} from './routes/custom-images-details-route'
import {
  CustomImageVersionsPageEntrypointForOrg,
  CustomImageVersionsPageEntrypointForEnterprise,
} from './routes/CustomImageVersionsListPage'
import {customImagesEnterpriseRoute} from './routes/custom-images-list-enterprise-route'
import {customImageVersionsEnterpriseRoute} from './routes/custom-images-details-enterprise-route'

export const customImagesStafftoolsApp = customImagesStafftoolsAppBuilder.createDataRouterAppFromRoutes([
  customImagesRoute.toRoute({
    Component: CustomImageListPageEntrypointForOrg,
  }),
  customImageVersionsRoute.toRoute({
    Component: CustomImageVersionsPageEntrypointForOrg,
  }),
  customImagesEnterpriseRoute.toRoute({
    Component: CustomImageListPageEntrypointForEnterprise,
  }),
  customImageVersionsEnterpriseRoute.toRoute({
    Component: CustomImageVersionsPageEntrypointForEnterprise,
  }),
])

registerDataRouterApp(customImagesStafftoolsApp)
