import {ActionList, ActionMenu, IconButton, VisuallyHidden} from '@primer/react'
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {DataTable} from '@primer/react/experimental'
import {useNavigate} from '@github-ui/use-navigate'
import type {ImageDefinition} from '../types/types'
import {customImageDetailsUrl} from '../helpers/urls'
import {ImageDefinitionGenericStatusIndicator} from './ImageDefinitionGenericStatusIndicator'

interface CustomImagesTableProps {
  images: ImageDefinition[]
  baseUrl: string
}

export function CustomImagesTable(props: CustomImagesTableProps) {
  const navigate = useNavigate()

  return (
    <DataTable
      aria-labelledby="custom-images"
      aria-describedby="custom-images-subtitle"
      data={props.images}
      cellPadding="condensed"
      initialSortColumn="id"
      initialSortDirection="ASC"
      columns={[
        {
          header: 'ID',
          field: 'id',
          rowHeader: true,
          sortBy: 'basic',
        },
        {
          header: 'Name',
          field: 'name',
          sortBy: 'alphanumeric',
        },
        {
          header: 'Platform',
          id: 'platform',
          renderCell: row => (
            <>
              {row.osType} ({row.architecture})
            </>
          ),
        },
        {
          header: 'Enabled',
          field: 'enabled',
          renderCell: row => <ImageDefinitionGenericStatusIndicator value={row.enabled} />,
        },
        {
          header: 'Versions',
          field: 'imageVersionsCount',
          renderCell: row => {
            return row.imageVersionsCount
          },
        },
        {
          id: 'actions',
          header: () => <VisuallyHidden>Actions</VisuallyHidden>,
          renderCell: row => {
            return (
              <ActionMenu>
                <ActionMenu.Anchor>
                  {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
                  <IconButton
                    aria-label={`Actions: ${row.name}`}
                    title={`Actions: ${row.name}`}
                    icon={KebabHorizontalIcon}
                    variant="invisible"
                    unsafeDisableTooltip
                  />
                </ActionMenu.Anchor>
                <ActionMenu.Overlay>
                  <ActionList>
                    <ActionList.Item onSelect={() => navigate(customImageDetailsUrl(props.baseUrl, row.id))}>
                      Details
                    </ActionList.Item>
                  </ActionList>
                </ActionMenu.Overlay>
              </ActionMenu>
            )
          },
        },
      ]}
    />
  )
}
